<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/functions.php';$pdo=db();$charities=$pdo->query("SELECT c.*,u.name contact_name,COUNT(DISTINCT cr.id) active_requests,COALESCE(SUM(CASE WHEN cr.status='active' THEN 1 ELSE 0 END),0) live_needs FROM charities c JOIN users u ON u.id=c.user_id LEFT JOIN clothing_requests cr ON cr.charity_id=c.id GROUP BY c.id ORDER BY c.verified DESC,c.organization_name")->fetchAll();$pageTitle='Explore charities';require __DIR__ . '/../includes/header.php'; ?>
<section class="page-hero"><div class="shell"><span class="eyebrow" style="color:#FFD928">Who we match with</span><h1>Meet the charities doing the work.</h1><p>Every clothing request is published and managed by an organisation with a real collection process.</p></div></section><section class="section"><div class="shell"><div class="request-grid"><?php foreach($charities as $c):?><article class="panel"><span class="status <?=$c['verified']?'status-success':'status-neutral'?>"><?=$c['verified']?'verified charity':'organisation profile'?></span><h2 style="margin:13px 0 7px"><?=e($c['organization_name'])?></h2><p class="section-description"><?=e($c['description']?:'A community organisation using clothing donations where they are needed most.')?></p><div class="request-meta"><span class="chip"><?=$c['live_needs']?> live needs</span><span class="chip">📍 <?=e($c['address']?:'Location shared on request')?></span></div><a class="button button-small" href="<?=e(url('donor/browse.php?charity='.$c['id']))?>">See clothing needs →</a></article><?php endforeach;?></div></div></section>
